INSERT INTO timeline_events
  (id, location_id, period_label, description, sort_year, sort_order, is_tradition, source_file)
VALUES
  ('tl-jerusalem-01', 'jerusalem', 'Canaanite era (from the Early Bronze Age, 4,000+ years ago)', 'The Canaanites are believed to have founded the city, known as Urusalim / Urshalem. The name is thought to derive from the Canaanite deity "Shalem". They built defences and water systems; the Gihon Spring was the main water source.', -2000, 0, TRUE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-02', 'jerusalem', 'Ancient Israelite era (c. 1000 BCE)', 'According to accounts in the Old Testament, Jerusalem became the capital under King David, and his son Solomon built the First Temple.', -1000, 1, TRUE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-03', 'jerusalem', '586 BCE', 'The Babylonian king Nebuchadnezzar II attacked the city, destroyed the First Temple, and deported a large part of the population (the Babylonian Exile).', -586, 2, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-04', 'jerusalem', 'Persian era (from 539 BCE)', 'Cyrus the Great took Babylon and permitted the return to Jerusalem and the rebuilding of the Temple; the Second Temple was built around 516 BCE.', -539, 3, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-05', 'jerusalem', 'Hellenistic era (from 332 BCE)', 'Alexander the Great conquered the region; control passed between the Ptolemies and the Seleucids. Attempts to impose Greek culture led to the Maccabean revolt in the 2nd century BCE and a period of Hasmonean independence.', -332, 4, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-06', 'jerusalem', 'Roman era (from 63 BCE)', 'Pompey entered Jerusalem. Under Herod the Great the city saw major construction and the Second Temple was expanded. In 70 CE, after the First Jewish Revolt, Titus besieged the city and destroyed the Second Temple; part of the retaining wall survives and is known as al-Buraq Wall (the Western Wall).', -63, 5, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-07', 'jerusalem', 'Byzantine era (324-638 CE)', 'After Constantine I adopted Christianity, Jerusalem became a major Christian holy city. The Church of the Holy Sepulchre was built in 335 CE. Churches, monasteries, roads and markets expanded.', 324, 6, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-08', 'jerusalem', 'Islamic conquest (638 CE)', 'Caliph Umar ibn al-Khattab entered the city peacefully at the request of Patriarch Sophronius, without destruction or displacement. He issued the Umariyya Covenant guaranteeing the safety of the inhabitants, their property and their places of worship.', 638, 7, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-09', 'jerusalem', 'Umayyad era (661-750 CE)', 'The Dome of the Rock was built by order of Caliph Abd al-Malik ibn Marwan, completed in 691-692 CE. Caliph al-Walid ibn Abd al-Malik completed Al-Aqsa Mosque in the early 8th century CE.', 661, 8, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-10', 'jerusalem', 'Abbasid and Fatimid eras', 'Repeated restoration work after earthquakes, including rebuilding parts of Al-Aqsa Mosque after the major earthquake of 1033 CE. Schools, libraries and pilgrim facilities were built.', 750, 9, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-11', 'jerusalem', 'Crusader occupation (1099-1187 CE)', 'The First Crusade took the city after a long siege. Historical sources record widespread violence against Muslim and Jewish inhabitants. Jerusalem became the capital of the Latin Kingdom.', 1099, 10, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-12', 'jerusalem', 'Ottoman era (16th century CE)', 'Sultan Suleiman the Magnificent rebuilt the city walls that still stand today.', 1550, 11, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-jerusalem-13', 'jerusalem', '1981 / 1982', 'The Old City and its walls were inscribed on the UNESCO World Heritage List (1981) and added to the List of World Heritage in Danger (1982).', 1981, 12, FALSE, 'content/ai-ready/old-city-jerusalem-summary.md'),
  ('tl-bethlehem-01', 'bethlehem', 'Canaanite era (2nd millennium BCE)', 'Archaeological finds show Bethlehem was inhabited from the 2nd millennium BCE, founded by Canaanites who built fortified towns and trading centres. It sat on old trade routes linking Jerusalem and Hebron to the south, and lived on agriculture, olive and vine cultivation, and sheep herding.', -2000, 0, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-02', 'bethlehem', 'Name origin', 'The name comes from Canaanite. Bayt means house or place; Lahm / Lakhm is linked by some researchers to an ancient Canaanite deity named Lakhm, while other readings give "house of bread" in the Semitic languages.', -1500, 1, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-03', 'bethlehem', '4th century CE (Byzantine)', 'Emperor Constantine I and his mother Helena ordered the building of the Church of the Nativity; it was completed around 339 CE.', 350, 2, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-04', 'bethlehem', '6th century CE', 'Emperor Justinian I rebuilt parts of the church after it was damaged.', 550, 3, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-05', 'bethlehem', 'Crusader era (from 1099 CE)', 'Bethlehem became part of the Latin Kingdom of Jerusalem. The Crusaders restored the Church of the Nativity and decorated it with mosaics and wall paintings, and built monasteries and pilgrim facilities. The city became a main stop on the Christian pilgrimage route.', 1099, 4, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-06', 'bethlehem', 'Ayyubid era (1187-1250 CE)', 'After Salah al-Din''s victory at Hattin in 1187 CE, Bethlehem came under Ayyubid rule. The Church of the Nativity kept its religious role and Christian pilgrims continued to visit; the holy places were respected.', 1187, 5, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-07', 'bethlehem', 'Mamluk era (1250-1517 CE)', 'The city retained its religious standing and continued to receive pilgrims. Restoration work was carried out on religious buildings and access roads, and pilgrimage routes were secured, supporting trade.', 1250, 6, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-08', 'bethlehem', 'Ottoman era (1517-1917 CE)', 'About four centuries of relative stability. Agriculture flourished - olives, vines and almonds - and the olive-wood craft industry developed into the city''s best-known traditional industry. The Church of the Nativity underwent several restorations.', 1517, 7, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-09', 'bethlehem', 'British Mandate (1917-1948)', 'Roads and services improved; the city continued its religious and tourist role while being affected by the political events of the period.', 1917, 8, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-10', 'bethlehem', 'Modern era', 'After 1948 Bethlehem came under Jordanian administration; in 1967 it became part of the territory occupied by Israel; since 1995 it has been administered by the Palestinian National Authority under the agreements signed at that time.', 1948, 9, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-11', 'bethlehem', '2012', 'The Church of the Nativity and the Pilgrimage Route were inscribed on the UNESCO World Heritage List.', 2012, 10, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-bethlehem-12', 'bethlehem', '2019', 'The site was removed from the List of World Heritage in Danger after the required conservation work was completed.', 2019, 11, FALSE, 'content/ai-ready/bethlehem-summary.md'),
  ('tl-sebastia-01', 'sebastia', 'Canaanite era (2nd millennium BCE)', 'Archaeological evidence shows the area was inhabited from the 2nd millennium BCE by Canaanites, who used the elevated position to protect the town and watch the trade routes. They lived on agriculture, livestock, trade, and water storage in wells and cisterns.', -2000, 0, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-02', 'sebastia', '9th century BCE', 'The ancient Canaanite name of the city was Shomron (Samaria); it was the capital of the northern Kingdom of Israel.', -900, 1, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-03', 'sebastia', '27 BCE', 'Herod the Great rebuilt the city and named it Sebastia - the Greek equivalent of the title of the Roman emperor Augustus - in his honour. The name "Samaria" remained in use in some historical and religious sources.', -27, 2, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-04', 'sebastia', 'Roman era', 'Major construction: the colonnaded street, the theatre, and the Temple of Augustus built by Herod the Great.', -63, 3, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-05', 'sebastia', 'Byzantine era', 'The city prospered; excavations revealed mosaic floors, columns, and remains of religious buildings. A cathedral was built at the site associated with John the Baptist.', 324, 4, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-06', 'sebastia', 'Islamic conquest (638 CE)', 'Sebastia came under Islamic rule during the conquest of the Levant under Caliph Umar ibn al-Khattab. It remained inhabited, existing buildings were largely preserved, and new buildings were added.', 638, 5, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-07', 'sebastia', 'Crusader era (1099-1187 CE)', 'The Crusaders rebuilt a large church over the site attributed to the tomb of John the Baptist, and built defensive structures and towers. The town became a stop for European pilgrims; remains of the Crusader church still stand.', 1099, 6, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-08', 'sebastia', 'Ayyubid and Mamluk eras', 'After Salah al-Din al-Ayyubi restored Muslim rule, parts of the Crusader church were converted during the Mamluk period into the Mosque of Nabi Yahya, keeping much of the original building. The town continued as an agricultural village.', 1187, 7, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-09', 'sebastia', 'Ottoman era (1517-1917 CE)', 'Sebastia became a small Palestinian village living on olives and olive oil, figs, grapes and almonds, and sheep and goat herding. Its Roman and Byzantine remains continued to attract European travellers and researchers who described them in their books.', 1517, 8, FALSE, 'content/ai-ready/sebastia-summary.md'),
  ('tl-sebastia-10', 'sebastia', 'Modern era', 'After Ottoman rule the area came under the British Mandate, then Jordanian administration after 1948. Since 1967 it has been within the territory occupied by Israel, while the Palestinian town is administered in civil matters by the Palestinian National Authority, with administrative complications tied to the archaeological site.', 1948, 9, FALSE, 'content/ai-ready/sebastia-summary.md');
INSERT INTO media
  (id, location_id, type, url, thumb_url, subject, description, era, pair_role,
INSERT INTO quiz_questions
  (id, location_id, question, options, answer_index, explanation, source_note, sort_order)
VALUES
  ('quiz-jer-1', 'jerusalem', 'When was the Dome of the Rock completed?', ARRAY['335 CE', '638 CE', '691-692 CE', '1099 CE'], 2, 'It was built by order of the Umayyad Caliph Abd al-Malik ibn Marwan and completed in 691-692 CE.', 'Timeline, Umayyad era - content/ai-ready/old-city-jerusalem-summary.md', 0),
  ('quiz-jer-2', 'jerusalem', 'Who rebuilt the walls that surround the Old City today?', ARRAY['Herod the Great', 'Emperor Constantine I', 'Caliph Umar ibn al-Khattab', 'Sultan Suleiman the Magnificent'], 3, 'The present walls were rebuilt in the 16th century CE under the Ottoman Sultan Suleiman the Magnificent. Much of what they enclose is far older.', 'Short overview and timeline, Ottoman era', 1),
  ('quiz-jer-3', 'jerusalem', 'How many quarters does the Old City contain?', ARRAY['Two', 'Three', 'Four', 'Eight'], 2, 'Four: the Muslim, Christian, Armenian and Jewish quarters. Eight is the number of historic gates.', 'Important facts', 2),
  ('quiz-jer-4', 'jerusalem', 'When did Caliph Umar ibn al-Khattab enter Jerusalem?', ARRAY['638 CE', '691 CE', '1099 CE', '1187 CE'], 0, 'He entered peacefully in 638 CE at the request of Patriarch Sophronius, and issued a covenant guaranteeing the inhabitants their lives, property and places of worship.', 'Timeline, Islamic conquest', 3),
  ('quiz-bet-1', 'bethlehem', 'Who ordered the building of the Church of the Nativity?', ARRAY['Justinian I', 'Constantine I and his mother Helena', 'Salah al-Din al-Ayyubi', 'Herod the Great'], 1, 'Constantine I and Helena ordered it in the 4th century CE; it was completed around 339 CE. Justinian I rebuilt parts of it in the 6th century after damage.', 'Timeline and main landmarks - content/ai-ready/bethlehem-summary.md', 0),
  ('quiz-bet-2', 'bethlehem', 'Roughly how far is Bethlehem from Jerusalem?', ARRAY['About 2 km', 'About 10 km', 'About 40 km', 'About 100 km'], 1, 'About 10 km south of Jerusalem, on a plateau roughly 775 m above sea level.', 'Short overview and important facts', 1),
  ('quiz-bet-3', 'bethlehem', 'Which crafts is Bethlehem best known for?', ARRAY['Glassblowing and pottery', 'Olive-wood carving and mother-of-pearl', 'Carpet weaving', 'Copper engraving'], 1, 'Olive-wood objects and mother-of-pearl work, alongside Palestinian embroidery.', 'Cultural and religious importance', 2),
  ('quiz-bet-4', 'bethlehem', 'In which year was the Church of the Nativity removed from UNESCO''s List of World Heritage in Danger?', ARRAY['2012', '2015', '2019', 'It is still on the list'], 2, 'It was inscribed on the World Heritage List in 2012 and removed from the danger list in 2019, once the required conservation work was completed.', 'Timeline, 2012 and 2019 entries', 3),
  ('quiz-seb-1', 'sebastia', 'Who rebuilt the city in 27 BCE and gave it the name Sebastia?', ARRAY['Pompey', 'Herod the Great', 'Emperor Augustus', 'Alexander the Great'], 1, 'Herod the Great rebuilt it and named it Sebastia, the Greek form of the title of the emperor Augustus, in his honour.', 'Timeline, 27 BCE - content/ai-ready/sebastia-summary.md', 0),
  ('quiz-seb-2', 'sebastia', 'What was the city called before it was named Sebastia?', ARRAY['Shomron (Samaria)', 'Neapolis', 'Caesarea', 'Sebaste'], 0, 'Its ancient Canaanite name was Shomron - Samaria - and it was the capital of the northern Kingdom of Israel in the 9th century BCE.', 'Timeline, 9th century BCE', 1),
  ('quiz-seb-3', 'sebastia', 'The Mosque of Nabi Yahya was converted from which building?', ARRAY['A Roman temple', 'A Byzantine cathedral rebuilt by the Crusaders', 'An Ottoman caravanserai', 'A Canaanite storehouse'], 1, 'A cathedral was built in the Byzantine period at the site associated with John the Baptist, rebuilt by the Crusaders, and partly converted into the Mosque of Nabi Yahya under the Mamluks.', 'Main landmarks and timeline, Ayyubid and Mamluk eras', 2),
  ('quiz-seb-4', 'sebastia', 'Which Roman structure at Sebastia is among the best preserved in Palestine?', ARRAY['The aqueduct', 'The bath house', 'The colonnaded street', 'The city forum'], 2, 'The colonnaded street, flanked by two rows of massive columns that once carried porticoes for merchants.', 'Important facts and main landmarks', 3);
